pipeline {
    agent any

    environment {
        PROJECT_NAME = 'data-big-platform-web'
        VERSION = '1.0.0'
        PORT = 9002
        DOCKER_REGISTRY = '10.0.0.59:15000' // 替换为你的Docker仓库地址
        REMOTE_HOST = '10.0.0.41' // 远程服务器地址
        REMOTE_USER = 'root' // 远程服务器用户名
        REMOTE_CREDENTIALS_ID = 'server-18-credentials-id' // Jenkins中保存的远程服务器SSH凭证ID
        TIMESTAMP = new Date().format("yyyyMMddHHmmss", TimeZone.getTimeZone('UTC'))
        DIST_PATH = '/dist-test'
    }

    stages {
        stage('Git') {
            steps {
                echo "Trying to checkout code from gitlab branch: ${params.Branch}"
                checkout scmGit(branches: [[name: "${params.Branch}"]], extensions: [], userRemoteConfigs: [[credentialsId: 'SSH-KEY-FOR-GITLAB', url: 'ssh://git@106.227.89.18:10093/front/databigplatform.git']])
            }
        }

        stage('Npm Install') {
            steps {
                // sh 'npm install'
                sh 'pnpm install'
            }
        }

        stage('Npm Build') {
            steps {
                // sh 'npm run build'
                sh 'npm run build:test'
            }
        }

        stage('Build Image') {
            steps {
                script {
                    try {
                        echo 'try to remove old image before build.'
                        sh "docker rmi ${PROJECT_NAME}:${VERSION}"
                        echo 'old image(${PROJECT_NAME}:${VERSION}) removed.'
                    } catch (Exception e) {
                        echo 'nothing to remove.'
                    }

                    echo 'try to build the image.'
                    sh "docker build -t ${PROJECT_NAME}:${VERSION} --build-arg DIST_PATH=${DIST_PATH} -f \"devops/Dockerfile\" ."
                    echo 'image(${PROJECT_NAME}:${VERSION}) is built.'
                }
            }
        }

        stage('Push Image') {
            steps {
                script {
                    try{
                        def timestamp = new Date().format("yyyyMMddHHmmss", TimeZone.getTimeZone('UTC'))
                        sh " docker login --username=admin --password=bigdata888888 ${DOCKER_REGISTRY}"
                        sh " docker tag ${PROJECT_NAME}:${VERSION} ${DOCKER_REGISTRY}/${PROJECT_NAME}:${VERSION}-${env.TIMESTAMP}"
                        sh " docker push ${DOCKER_REGISTRY}/${PROJECT_NAME}:${VERSION}-${env.TIMESTAMP}"
                        echo 'image(${PROJECT_NAME}:${VERSION}-${env.TIMESTAMP}) is pushed to the registry.'
                    } catch (Exception e) {
                        echo 'push image failed'
                        echo "Caught exception: ${e.getMessage()}"
                    }
                }
            }
        }

        stage('Deploy to Remote') {
            steps {
                script {
                    sshagent([REMOTE_CREDENTIALS_ID]) {
                        sh """
                            ssh ${REMOTE_USER}@${REMOTE_HOST} '
                                    docker login -u admin -p bigdata888888 ${DOCKER_REGISTRY} &&
                                    docker pull ${DOCKER_REGISTRY}/${PROJECT_NAME}:${VERSION}-${env.TIMESTAMP} &&
                                    docker stop ${PROJECT_NAME} || true &&
                                    docker rm ${PROJECT_NAME} || true &&
                                    docker run -d --name ${PROJECT_NAME} -p ${PORT}:80 -e TZ=Asia/Shanghai ${DOCKER_REGISTRY}/${PROJECT_NAME}:${VERSION}-${env.TIMESTAMP} '
                        """
                    }
                }
            }
        }
    }
}
